os.environ['PYTHONDONTWRITEBYTECODE']='1'
import pathlib,json,hashlib,xml.etree.ElementTree as E,zipfile,base64,zlib,time
import numpy as np,trimesh
from numba import njit
from rtree import index
from scipy.spatial import cKDTree
W=pathlib.Path(__file__).parent

def load():
 r=E.parse(W/'6158-21_labeledPrepFinal.vtp').getroot(); raw=r.find('AppendedData').text.strip()[1:]
 def arr(a):
  s=raw[int(a.attrib['offset']):]; nb=int(np.frombuffer(base64.b64decode(s[:16]),dtype='<u4')[0]); hl=4*(3+nb);el=4*((hl+2)//3)
  h=np.frombuffer(base64.b64decode(s[:el]),dtype='<u4'); b=base64.b64decode(s[el:el+4*((int(sum(h[3:]))+2)//3)])
  data=b'';off=0
  for sz in h[3:]:data+=zlib.decompress(b[off:off+sz]);off+=sz
  dt={'Float32':'<f4','Float64':'<f8','Int64':'<i8'}[a.attrib['type']]
  return np.frombuffer(data,dtype=dt).copy()
 p=r.find('PolyData/Piece');sv=arr(p.find('Points/DataArray')).reshape(-1,3).astype(float)
 sf=arr(p.find('Polys/DataArray[@Name="connectivity"]')).reshape(-1,3);offset=arr(p.find('Polys/DataArray[@Name="offsets"]'));assert np.all(np.diff(np.r_[0,offset])==3)
 labels=arr(p.find('CellData/DataArray[@Name="Label"]'));assert len(labels)==len(sf)
 z=zipfile.ZipFile(W/'6158-21_KATANA_ML_R2.3mf'); root=E.fromstring(z.read('3D/3dmodel.model'));ns={'m':'http://schemas.microsoft.com/3dmanufacturing/core/2015/02'}
 mesh=root.find('.//m:mesh',ns); v=np.array([[float(a.attrib[k]) for k in ['x','y','z']] for a in mesh.find('m:vertices',ns)])
 f=np.array([[int(a.attrib[k]) for k in ['v1','v2','v3']] for a in mesh.find('m:triangles',ns)])
 roles=np.array([int(a.attrib['p1']) for a in mesh.find('m:triangles',ns)])
 stl=trimesh.load_mesh(W/'6158-21_KATANA_ML_R2.stl',process=False)
 return sv,sf,labels,v,f,roles,stl,root.attrib

def dump(n,x):
 def clean(v):
  if isinstance(v,(np.generic,np.ndarray)):return clean(v.tolist())
  if isinstance(v,dict):return {k:clean(a) for k,a in v.items()}
  if isinstance(v,(list,tuple)):return [clean(a) for a in v]
  return v
 (W/(n+'.json')).write_text(json.dumps(clean(x),indent=2)); print(n,json.dumps(clean(x))[:1500],flush=True)

@njit(cache=True)
def dot(a,b): return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]
@njit(cache=True)
def cross(a,b):return np.array([a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]])
@njit(cache=True)
def psq(p,a,b):
 d=b-a;t=dot(p-a,d)/max(dot(d,d),1e-300);t=min(1.,max(0.,t));q=p-a-t*d;return dot(q,q)
@njit(cache=True)
def ptsq(p,t):
 a,b,c=t;ab=b-a;ac=c-a;n=cross(ab,ac);nn=dot(n,n)
 if nn<1e-30:return min(psq(p,a,b),psq(p,b,c),psq(p,c,a))
 q=p-n*dot(p-a,n)/nn;ap=q-a
 aa=dot(ab,ab);bb=dot(ab,ac);cc=dot(ac,ac);u=dot(ap,ab);v=dot(ap,ac);den=aa*cc-bb*bb
 s=(cc*u-bb*v)/den;tt=(aa*v-bb*u)/den
 if s>=0 and tt>=0 and s+tt<=1:return dot(p-q,p-q)
 return min(psq(p,a,b),psq(p,b,c),psq(p,c,a))
@njit(cache=True)
def sssq(p,q,r,s):
 # Closest points of two finite segments, including constrained end points.
 u=q-p;v=s-r;w=p-r;a=dot(u,u);b=dot(u,v);c=dot(v,v);d=dot(u,w);e=dot(v,w);den=a*c-b*b
 best=min(psq(p,r,s),psq(q,r,s),psq(r,p,q),psq(s,p,q))
 if den>1e-28:
  x=(b*e-c*d)/den;y=(a*e-b*d)/den
  if 0<=x<=1 and 0<=y<=1:
   w=w+x*u-y*v;best=min(best,dot(w,w))
 return best
@njit(cache=True)
def segtri(p,q,t):
 d=q-p;e1=t[1]-t[0];e2=t[2]-t[0];h=cross(d,e2);det=dot(e1,h)
 if abs(det)<1e-18:return False
 a=p-t[0];u=dot(a,h)/det
 if u<0 or u>1:return False
 h2=cross(a,e1);v=dot(d,h2)/det
 if v<0 or u+v>1:return False
 w=dot(e2,h2)/det
 return 0<=w<=1
@njit(cache=True)
def trisq(a,b):
 best=1e300
 for i in range(3):
  if segtri(a[i],a[(i+1)%3],b) or segtri(b[i],b[(i+1)%3],a):return 0.
  best=min(best,ptsq(a[i],b),ptsq(b[i],a))
  for j in range(3):best=min(best,sssq(a[i],a[(i+1)%3],b[j],b[(j+1)%3]))
 return best
@njit(cache=True)
def pairdist(a,b,ii,jj):
 out=np.empty(len(ii))
 for k in range(len(ii)):out[k]=trisq(a[ii[k]],b[jj[k]])
 return out

def tree(tri):
 p=index.Property();p.dimension=3
 return index.Index(((i,tuple(np.r_[t.min(0),t.max(0)]),None) for i,t in enumerate(tri)),properties=p)

def distances(a,b,radius,name):
 tr=tree(b);mins=np.full(len(a),np.inf);ids=np.full(len(a),-1);tested=0
 for start in range(0,len(a),128):
  ii=[];jj=[]
  for i in range(start,min(start+128,len(a))):
   js=list(tr.intersection(tuple(np.r_[a[i].min(0)-radius,a[i].max(0)+radius])))
   ii.extend([i]*len(js));jj.extend(js)
  ii=np.array(ii,dtype=np.int64);jj=np.array(jj,dtype=np.int64);dd=pairdist(a,b,ii,jj);tested+=len(ii)
  for i in np.unique(ii):
   ix=np.flatnonzero(ii==i);ix=ix[np.argmin(dd[ix])];mins[i]=dd[ix];ids[i]=jj[ix]
 idx=int(np.argmin(mins));val=float(np.sqrt(mins[idx]));assert val<radius
 out=dict(min_source=val,query_face=idx,support_face=int(ids[idx]),query_faces=len(a),support_faces=len(b),tested_pairs=tested,broadphase_radius_source=radius,certified_global_minimum=True,tolerance_source=1e-9,below_040_faces=int(np.sum(mins<.04**2)),below_050_faces=int(np.sum(mins<.05**2)))
 dump(name,out);np.savez_compressed(W/(name+'_facets.npz'),minimum_squared=mins,support_face=ids)
 return out

def boundary(f):
 e=np.concatenate([f[:,[0,1]],f[:,[1,2]],f[:,[2,0]]]);u,c=np.unique(np.sort(e,axis=1),axis=0,return_counts=True);return u[c==1]

def basic():
 sv,sf,l,v,f,roles,stl,attrs=load();m=trimesh.Trimesh(v,f,process=False);cap=sf[l==1];inner=f[roles==1];outer=f[roles==0]
 _,counts=np.unique(np.sort(m.edges,axis=1),axis=0,return_counts=True)
 # Explicit vertex link condition; edge count alone does not establish a 2-manifold.
 vf=[[] for _ in v]
 for face in f:
  for i in face:vf[i].append([int(a) for a in face if a!=i])
 badlinks=[]
 for i,ed in enumerate(vf):
  adj={}
  for a,b in ed:adj.setdefault(a,set()).add(b);adj.setdefault(b,set()).add(a)
  seen=set();stack=[next(iter(adj))]
  while stack:
   k=stack.pop()
   if k in seen:continue
   seen.add(k);stack.extend(adj[k]-seen)
  if len(seen)!=len(adj) or any(len(a)!=2 for a in adj.values()):badlinks.append(i)
 ivids=np.unique(inner);pvids=np.unique(cap);_,inv=np.unique(cap,return_inverse=True);compact=inv.reshape(-1,3)
 # The export retains source face ordering; independently verify each index and displacement.
 mapping={int(x):i for i,x in enumerate(ivids)};ifc=np.array([[mapping[int(x)] for x in a] for a in inner]);connectivity=np.array_equal(np.sort(ifc,axis=1),np.sort(compact,axis=1))
 displacement=np.linalg.norm(v[ivids]-sv[pvids],axis=1)
 dump('basic',dict(source_vertices=len(sv),source_faces=len(sf),source_label1_faces=len(cap),vertices=len(v),faces=len(f),role_counts={str(k):int(sum(roles==k)) for k in np.unique(roles)},stl_3mf_triangle_identity=bool(np.array_equal(stl.triangles,v[f])),unit_3mf=attrs.get('unit'),bounds_source=np.ptp(sv,axis=0),bounds_crown=np.ptp(v,axis=0),watertight=m.is_watertight,winding_consistent=m.is_winding_consistent,components=len(m.split(only_watertight=False)),euler_number=m.euler_number,edge_incidence_not_two=int(sum(counts!=2)),vertex_links_not_single_cycle=badlinks,degenerate_faces=int(sum(m.area_faces<1e-14)),duplicate_faces=int(len(f)-len(np.unique(np.sort(f,axis=1),axis=0))),volume=m.volume,inner_source_connectivity_matches=connectivity,paired_vertex_displacement_range=[displacement.min(),displacement.max()],facet_upper_distance_bound=displacement.max(),upper_bound_justification='For each corresponding triangle, affine barycentric pairing and convexity of norm bound EVERY point distance in BOTH directions by the largest of its three vertex displacements; topology correspondence checked for all facets.'))
 assert connectivity
 distances(v[inner],sv[sf],.061,'gap_to_whole_die')
 distances(v[inner],sv[cap],.061,'gap_to_prepared_cap')
 distances(v[outer],v[inner],.8,'wall')
 np.savez_compressed(W/'independent_loaded.npz',sv=sv,sf=sf,labels=l,v=v,f=f,roles=roles,source_boundary=boundary(cap),inner_boundary=boundary(inner))
if __name__=='__main__':basic()

