from verify_geometry import *
@njit(cache=True)
def separated(a,b,axis,delta):
 nn=dot(axis,axis)
 if nn<1e-28:return False,0.
 mn=1e300;mx=-1e300;bn=1e300;bx=-1e300
 shift=dot(delta,axis)
 for i in range(3):
  aa=dot(a[i],axis);bb=dot(b[i],axis);mn=min(mn,aa,aa+shift);mx=max(mx,aa,aa+shift);bn=min(bn,bb);bx=max(bx,bb)
 gap=max(bn-mx,mn-bx)/np.sqrt(nn)
 return gap>1e-10,gap
@njit(cache=True)
def sweep_hit(a,b,delta):
 ea=np.empty((3,3));eb=np.empty((3,3))
 for i in range(3):ea[i]=a[(i+1)%3]-a[i];eb[i]=b[(i+1)%3]-b[i]
 axes=np.empty((17,3));axes[0]=cross(ea[0],ea[1]);axes[1]=cross(eb[0],eb[1]);k=2
 for i in range(3):axes[k]=cross(ea[i],delta);k+=1
 for i in range(3):
  for j in range(3):axes[k]=cross(ea[i],eb[j]);k+=1
 for i in range(3):axes[k]=cross(delta,eb[i]);k+=1
 best=-1e300
 for axis in axes:
  sep,gap=separated(a,b,axis,delta);best=max(best,gap)
  if sep:return False,gap
 return True,best
@njit(cache=True)
def swept_batch(a,b,ii,jj,delta):
 hits=np.zeros(len(ii),dtype=np.bool_);gaps=np.empty(len(ii))
 for k in range(len(ii)):hits[k],gaps[k]=sweep_hit(a[ii[k]],b[jj[k]],delta)
 return hits,gaps

def sweep(v,f,sv,sf,axis,distance,name):
 # Rigid orthonormal rotation improves broadphase. The continuous swept hull
 # is triangle + [0,delta]. Full polyhedron/triangle SAT includes face normals
 # and every cross product of the two sets of edge directions.
 e=np.array([1.,0,0]);e-=axis*dot(e,axis);e/=np.linalg.norm(e);b=np.cross(axis,e);R=np.array([e,b,axis]).T
 a=(v@R)[f];t=(sv@R)[sf];delta=np.array([0.,0,distance]);tr=tree(t);tested=0;hitlist=[];mingap=np.inf
 for start in range(0,len(a),256):
  ii=[];jj=[]
  for i in range(start,min(start+256,len(a))):
   low=np.minimum(a[i].min(0),a[i].min(0)+delta);high=np.maximum(a[i].max(0),a[i].max(0)+delta)
   js=list(tr.intersection(tuple(np.r_[low-1e-10,high+1e-10])));ii.extend([i]*len(js));jj.extend(js)
  ii=np.array(ii,dtype=np.int64);jj=np.array(jj,dtype=np.int64);hits,gaps=swept_batch(a,t,ii,jj,delta);tested+=len(ii)
  if len(gaps):mingap=min(mingap,float(gaps.min()))
  for k in np.flatnonzero(hits):hitlist.append([int(ii[k]),int(jj[k])])
  if hitlist:break
 out=dict(status='FAIL' if hitlist else 'PASS',axis=axis,distance_source=distance,continuous_not_time_sampled=True,tested_candidate_pairs=tested,collision_pairs_first_batch=hitlist[:10],separating_axis_clearance_min_source=mingap,end_projection_separation_source=float(np.min(v@axis)+distance-np.max(sv@axis)),tolerance_source=1e-10)
 dump(name,out);return out

@njit(cache=True)
def intersection_away(p,q,t,shared):
 d=q-p;e1=t[1]-t[0];e2=t[2]-t[0];h=cross(d,e2);det=dot(e1,h)
 if abs(det)<1e-18:return False
 a=p-t[0];u=dot(a,h)/det;h2=cross(a,e1);vv=dot(d,h2)/det;w=dot(e2,h2)/det
 if u>=-1e-12 and vv>=-1e-12 and u+vv<=1+1e-12 and -1e-12<=w<=1+1e-12:
  pnt=p+w*d;return dot(pnt-shared,pnt-shared)>1e-18
 return False
@njit(cache=True)
def selfpairs(v,f,ii,jj):
 bad=np.zeros(len(ii),dtype=np.bool_)
 for k in range(len(ii)):
  fi=f[ii[k]];fj=f[jj[k]];a=v[fi];b=v[fj];shared=[]
  for x in fi:
   for y in fj:
    if x==y:shared.append(x)
  if len(shared)==0:bad[k]=trisq(a,b)<=1e-20
  elif len(shared)==3:bad[k]=True
  elif len(shared)==2:
   p=v[shared[0]];q=v[shared[1]];x=p;y=p
   for u in fi:
    if u!=shared[0] and u!=shared[1]:x=v[u]
   for u in fj:
    if u!=shared[0] and u!=shared[1]:y=v[u]
   na=cross(q-p,x-p);nb=cross(q-p,y-p)
   # Adjacent coplanar faces must occupy opposite halfplanes of common edge.
   cop=dot(cross(na,nb),cross(na,nb))<=1e-22*dot(na,na)*dot(nb,nb)
   bad[k]=cop and dot(na,nb)>0
  else:
   sh=v[shared[0]]
   for u in range(3):
    if intersection_away(a[u],a[(u+1)%3],b,sh) or intersection_away(b[u],b[(u+1)%3],a,sh):bad[k]=True
   # Remaining coplanar overlap: nonshared vertex lies on other triangle,
   # or opposite edges intersect (neither contains the common vertex).
   aa=np.empty((2,3));bb=np.empty((2,3));ia=0;ib=0
   for u in range(3):
    if fi[u]!=shared[0]:
     aa[ia]=a[u];ia+=1
     if ptsq(a[u],b)<=1e-20:bad[k]=True
    if fj[u]!=shared[0]:
     bb[ib]=b[u];ib+=1
     if ptsq(b[u],a)<=1e-20:bad[k]=True
   if sssq(aa[0],aa[1],bb[0],bb[1])<=1e-20:bad[k]=True
 return bad

def selfcheck(v,f):
 a=v[f];tr=tree(a);tested=0;bad=[]
 for start in range(0,len(a),256):
  ii=[];jj=[]
  for i in range(start,min(start+256,len(a))):
   js=[j for j in tr.intersection(tuple(np.r_[a[i].min(0)-1e-10,a[i].max(0)+1e-10])) if j>i];ii.extend([i]*len(js));jj.extend(js)
  ii=np.array(ii,dtype=np.int64);jj=np.array(jj,dtype=np.int64);hits=selfpairs(v,f,ii,jj);tested+=len(ii)
  bad.extend([[int(ii[k]),int(jj[k])] for k in np.flatnonzero(hits)])
 dump('self_intersections',dict(status='FAIL' if bad else 'PASS',pairs=bad[:20],count=len(bad),tested_pairs=tested,all_faces=len(f),adjacent_pairs_checked=True,tolerance_source=1e-10))

@njit(cache=True)
def curve_vertex_dist(points,segments):
 out=np.empty(len(points))
 for i,p in enumerate(points):
  best=1e300
  for a,b in segments:best=min(best,psq(p,a,b))
  out[i]=np.sqrt(best)
 return out
@njit(cache=True)
def curve_min(a,b):
 best=1e300;ii=0;jj=0
 for i in range(len(a)):
  for j in range(len(b)):
   d=sssq(a[i,0],a[i,1],b[j,0],b[j,1])
   if d<best:best=d;ii=i;jj=j
 return np.sqrt(best),ii,jj

def margins(sv,sf,l,v,f,roles):
 cap=sf[l==1];inn=f[roles==1];sb=boundary(cap);ib=boundary(inn);S=sv[sb];I=v[ib]
 ds=curve_vertex_dist(sv[np.unique(sb)],I);di=curve_vertex_dist(v[np.unique(ib)],S)
 mi,i,j=curve_min(S,I)
 mapping=dict(zip(np.unique(cap).tolist(),np.unique(inn).tolist()))
 paired_edges=np.array([[mapping[int(k)] for k in e] for e in sb])
 assert set(map(tuple,np.sort(paired_edges,axis=1)))==set(map(tuple,np.sort(ib,axis=1)))
 paired=np.linalg.norm(v[paired_edges]-sv[sb],axis=2)
 upper=float(paired.max())+1e-9
 dump('margin',dict(source_edges=len(S),export_inner_edges=len(I),source_vertices=len(np.unique(sb)),inner_vertices=len(np.unique(ib)),minimum_source=mi,minimum_source_segment=i,minimum_inner_segment=j,hausdorff_source_interval=[max(ds.max(),di.max())-1e-9,upper],max_vertex_to_curve_source_to_inner=ds.max(),max_vertex_to_curve_inner_to_source=di.max(),min_vertex_distance= min(ds.min(),di.min()),max_paired_displacement_source=float(paired.max()),boundary_correspondence_verified=True,numerical_tolerance_source=1e-9,physical_um=None,conditional_um_at_1mm_per_unit=dict(minimum=1000*mi,hausdorff_interval=[1000*(max(ds.max(),di.max())-1e-9),1000*upper]),criterion='R2 requires preserved correspondence and reporting the emitted offset; it explicitly does not claim zero physical marginal gap. No physical tolerance invented.'))

def write_mesh(path,v,f):
 with open(path,'w') as h:h.write(f'{len(v)} {len(f)}\n');np.savetxt(h,v,fmt='%.17g');np.savetxt(h,f,fmt='%d')

def main():
 sv,sf,l,v,f,roles,stl,attrs=load();axis=np.array([.11172378580168008,.3503527267366788,.9299305149065249]);assert abs(np.linalg.norm(axis)-1)<1e-14
 for name,vv,ff in [('crown',v,f),('inner',v,f[roles==1]),('outer',v,f[roles==0]),('source',sv,sf),('cap',sv,sf[l==1])]:write_mesh(W/(name+'.mesh'),vv,ff)
 selfcheck(v,f);margins(sv,sf,l,v,f,roles);sweep(v,f,sv,sf,axis,30.,'sweep')
 # Fault injection changes test input only; no candidate is designed/exported.
 sweep(v,f,sv,sf,axis,-30.,'sweep_wrong_direction_control')
if __name__=='__main__':main()

